using System.Net; using System.Net.Http.Json; using Microsoft.AspNetCore.Mvc.Testing; using Microsoft.Extensions.Configuration; namespace Backend.Api.Tests; public sealed class AuthAndWorkspaceTests(IClassFixture<WebApplicationFactory<Program>> fixture) : IClassFixture<WebApplicationFactory<Program>> { private readonly WebApplicationFactory<Program> _factory=fixture.WithWebHostBuilder(b=>b.ConfigureAppConfiguration((_,c)=>c.AddInMemoryCollection(new Dictionary<string,string?>{{"Authentication:Username","operator"},{"Authentication:Password","secret"},{"Authentication:SigningKey","test-signing-key-at-least-32-characters"},{"Authentication:SecureCookie","false"},{"ConnectionStrings:Default",$"Data Source={Path.Combine(Path.GetTempPath(),"auth-tests.db")}"}}))); [Fact] public async Task WorkspaceRequiresValidSession(){using var c=_factory.CreateClient();var denied=await c.GetAsync("/workspaces/1");Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);var login=await c.PostAsJsonAsync("/auth/login",new{Username="operator",Password="secret"});Assert.Equal(HttpStatusCode.OK,login.StatusCode);Assert.Contains("sdlc_session",login.Headers.GetValues("Set-Cookie").Single());} [Fact] public async Task InvalidLoginIsRejectedAndValidLoginAllowsWorkspaceAccess(){using var c=_factory.CreateClient(new WebApplicationFactoryClientOptions{HandleCookies=true});var bad=await c.PostAsJsonAsync("/auth/login",new{Username="operator",Password="wrong"});Assert.Equal(HttpStatusCode.Unauthorized,bad.StatusCode);var good=await c.PostAsJsonAsync("/auth/login",new{Username="operator",Password="secret"});Assert.Equal(HttpStatusCode.OK,good.StatusCode);var response=await c.GetAsync("/swagger/v1/swagger.json");Assert.Equal(HttpStatusCode.OK,response.StatusCode);} [Fact] public async Task TamperedCookieIsRejected(){using var c=_factory.CreateClient();c.DefaultRequestHeaders.Add("Cookie","sdlc_session=operator%7C9999999999%7Ctampered");var response=await c.GetAsync("/workspaces/1");Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);} }